  "system.auto.2enved.16": "Prompt canonique",
  "system.auto.1uliczp.15": "Comportement du canevas",
  "system.auto.1dpjkq9.28": "Le canevas est en cours de révision interne",
  "system.auto.1fc0tqj.262": "La disposition du canevas, les opérations sur le texte, les traits d’esquisse, les attestations de présentation d’images, les changements de membres, le contexte formalisé et les décisions relatives aux propositions sont conservés durablement. La présence, la position des curseurs, le survol, la zone visible et les trajectoires brutes des pointeurs sont exclus du vocabulaire des événements.",
  "system.auto.8kxag2.11": "Taille du canevas",
  "system.auto.rk53n8.11": "Synchronisation du canevas",
  "system.auto.asse13.19": "Limite de capacité",
  "system.auto.1szdb92.28": "Référence de l’attestation de capacité",
  "system.auto.m55dyi.73": "Saisissez des descriptions plus longues sans perdre les fonctions natives de modification et de validation.",
  "system.auto.rgebfv.278": "La collecte fonctionne uniquement lorsque document.visibilityState est visible. Elle enregistre la surface et le contexte sémantiques, les durées d’activité et d’inactivité, les identifiants des contenus visibles et l’action mettant fin à une séquence. Les trajectoires brutes du pointeur, les coordonnées, les touches, le texte saisi, le microphone et les données ambiantes de l’appareil sont exclus.",
