  "system.auto.17295fh.105": "Précisez exactement ce qui suscite votre réaction. Cette information peut modifier l’ordre des prochaines options, mais ne les exclut jamais.",
  "system.auto.1a7fp23.31": "Choisir l’atmosphère que doit dégager le travail",
  "system.auto.1x62wv9.78": "Choisissez une option à l’aide d’un véritable sélecteur natif et d’enregistrements d’options JavaScript.",
  "system.auto.1hi8bcc.48": "Choisissez plusieurs blocs, puis placez-les ensemble.",
  "system.auto.1212rr9.13": "Choisir la source",
  "system.auto.15tqkk2.230": "Choisissez la proposition de valeur créative que cette simulation doit démontrer, puis son parcours de développement, l’étendue de son historique et les fournisseurs concernés. Chaque simulation terminée est enregistrée pour pouvoir être rejouée et associée à un compte créateur fictif isolé.",
  "system.auto.5e9al0.88": "Choisissez le rôle de cette décision, puis précisez ce qu’elle doit apporter au résultat.",
  "system.auto.1a8xjrx.88": "Choisissez le type de décision créative à définir. Vous pourrez la modifier ou la supprimer ultérieurement.",
  "system.auto.b8re3k.126": "Choisissez le résultat qui facilitera votre prochaine décision. Chaque format donne accès à la même configuration complète que dans le document.",
  "system.auto.1h9xws8.87": "Choisissez d’abord le rôle, puis formulez la décision de façon à ce qu’un collaborateur puisse la mettre en œuvre.",
  "system.auto.7ng3do.21": "Choisir un événement visible…",
  "system.auto.p2hiqs.144": "Choisissez le type de décision, puis indiquez ce qui doit être exclu. Le rôle reste explicite tandis que l’intention devient une contrainte d’exclusion.",
  "system.auto.un9mrk.94": "Choisissez le type de décision géré par ce calque, puis définissez des instructions précises et son degré d’influence.",
