  "system.auto.4ty346.144": "images générées et images de référence persistantes. Les ensembles représentatifs et étendus optimisent la diversité spatiale ; Tout conserve l’intégralité du corpus disponible.",
  "system.auto.1ngdqhi.18": "opérations persistantes",
