  "system.auto.bewxox.39": "p. ex. l’espace calme derrière le sujet",
  "system.auto.tkzpxw.156": "Chaque action enregistre une disposition reproductible associée à cette sélection. Elle modifie uniquement la présentation du tableau ; le sens et le contenu de chaque idée restent intacts.",
  "system.auto.b7rujk.90": "Chaque application présente uniquement les commandes et les rapports nécessaires à son public autorisé.",
  "system.auto.nywtw1.95": "Chaque package approuvé est immuable, appartient au tenant et n’est appliqué qu’après la sélection d’un document.",
  "system.auto.1odr0s.177": "Chaque cohorte commence immédiatement et dure 30 jours. Réservez au moins une place à une personne chargée d’un examen indépendant. Utilisez uniquement des sources non sensibles que votre équipe est autorisée à fournir.",
  "system.auto.1ojvk5d.271": "Chaque image est traitée par les deux implémentations locales. La méthode actuelle conserve les proportions et sélectionne une zone d’attention cohérente ; la référence reproduit le centre de saillance de l’échantillon carré d’origine. Ces calculs ne sont volontairement pas ajoutés à un document.",
  "system.auto.17k50xd.157": "Chaque réponse est reliée aux décisions qui ont contribué au résultat. Ces liens montrent les éléments en jeu sans attribuer l’ensemble du résultat à un seul choix.",
  "system.auto.1ogqrvi.134": "Chaque section prépare une réussite différente : un objectif clair, un univers concret, une expression cohérente et un résultat livrable.",
  "system.auto.1gpduqd.71": "Chaque image de référence sélectionnée n’est examinée qu’une seule fois, et non pour chaque structure.",
  "system.auto.1c4rk11.132": "Chaque image autonome ou éventail de quatre images n’est compté qu’une seule fois. Une exploration pertinente reste visible au lieu d’être considérée à tort comme un abandon.",
