  "system.auto.4vwyow.63": "Toutes les décisions figurent ici. Les éléments les plus hauts sont traités en priorité.",
  "system.auto.1gy09yr.57": "Chaque décision restera disponible avec le résultat suivant",
  "system.auto.nbozd4.79": "Toute modification d’un document, d’un projet, d’un bloc, d’un contenu multimédia ou d’un compte demande une confirmation préalable",
  "system.auto.3bmjvo.11": "Chaque événement",
  "system.auto.10cfx34.52": "Chaque résultat finalisé peut devenir un contexte modifiable dans",
  "system.auto.1ldab7e.82": "Tous les critères d’acceptation figés sont satisfaits. Aucune requête fournisseur ni aucune évaluation n’a échoué.",
  "system.auto.d7at6p.13": "Chaque projet",
  "system.auto.58g7lk.226": "Chaque jalon fournisseur devient un projet isolé, avec ses documents, blocs, relations, références, brouillons, variantes d’instructions, collections et canevas. Ce processus ne copie ni ne modifie jamais les données existantes du compte.",
  "system.auto.1ya1rc5.95": "Chaque résultat découle des mêmes décisions et reste associé à ce document dans toutes les vues.",
  "system.auto.7kwaj6.183": "Toutes les images conservées et tous les échecs de génération de documents associés à ce document. Examinez l’instruction immuable, le contexte figé, le justificatif de référence et l’erreur technique propres à chaque tentative.",
  "system.auto.9o6gd6.17": "Chaque ligne indique",
  "system.auto.11b6xli.58": "Toutes les décisions et tous les résultats enregistrés figurent toujours ici.",
  "system.auto.16rfoqn.141": "Chaque image enregistrée reste visible, quelle que soit la position actuelle de relecture. Chaque carte indique à quel moment elle apparaît dans la projection de l’application.",
  "system.auto.1uqr942.59": "Chaque élément spatial reste accessible sans utiliser de dispositif de pointage.",
  "system.auto.1kd8oa5.94": "Chaque objectif observé à cette étape du parcours a été examiné ou volontairement mis de côté.",
  "system.auto.jmirga.26": "Tout ce qui façonne déjà",
  "system.auto.15oc54e.27": "Tout ce que contient ce document",
  "system.auto.17ylqsm.27": "Tout ce qui façonne le projet",
  "system.auto.beefcp.21": "Partout en dehors de cette zone",
  "system.auto.8wpfe2.185": "les preuves sont conservées comme non conformes. La dernière recherche a révélé des écarts sémantiques ainsi que des défaillances de fiabilité et de sécurité du fournisseur ; examinez les preuves de la campagne avant de préparer une nouvelle version.",
  "system.auto.4mexb4.23": "justificatifs de preuves affichés",
  "system.auto.a1dn9d.18": "Référence de la preuve",
  "system.auto.16uoj84.25": "Conservation des preuves (jours)",
  "system.auto.b5bzxd.7": "exact ·",
  "system.auto.kkammq.26": "Nombre exact d’événements persistants.",
  "system.auto.52fr29.54": "Requête privée exacte envoyée au processus de génération.",
  "system.auto.n02a4q.25": "Éléments typographiques exacts",
