  "system.auto.1f4ljlo.24": "example.com, example.org",
  "system.auto.1lr4ql4.10": "Exclusions",
  "system.auto.19jst71.20": "Limites d’exécution",
  "system.auto.1165k5g.157": "Testez le routage des fournisseurs avant d’engager des frais. Comparez la normalisation des requêtes, les limites des fonctionnalités, les étapes de progression et les tarifs actuellement publiés par les fournisseurs.",
  "system.auto.1229tpt.226": "Les références autorisées existantes sont traitées en parallèle lorsque cela est possible. Les transitions reposent sur des instructions textuelles ; le fournisseur ne prend pas en charge le verrouillage natif des images de début ou de fin, ni l’extraction d’images vidéo. Le résultat final est une séquence de scènes ordonnées.",
  "system.auto.gnzkyd.23": "Ensemble de comparaison existant",
