  "system.auto.nkhptm.28": "Suggestions à évaluer",
  "system.auto.9qbzoq.35": "suggestions que vous avez jugées utiles",
  "system.auto.hn5q8x.80": "Résumer une histoire, une présentation, un storyboard ou une création animée issus d’un document.",
  "system.auto.4m89ar.7": "résumé",
  "system.auto.j4h67y.135": "fournis ou préparés. Les justificatifs des pixels indiquent si les données ont atteint le fournisseur et contiennent des empreintes de hachage sans dupliquer les données d’images privées.",
  "system.auto.8uvcrg.26": "Formats créatifs pris en charge",
