  "system.auto.1125nmt.18": "signaux complémentaires",
  "system.auto.1oh2f0x.6": "Sélecteur",
  "system.auto.1u133ld.73": "Choisir parmi un petit nombre de boutons clairement identifiés, dont l’état actif est visible.",
  "system.auto.1vii0rj.21": "Synchronisation des modifications",
  "system.auto.kack2k.6": "système",
  "system.auto.1vwbe7u.19": "Système et gouvernance",
