  "system.auto.1aajk6f.22": "Ce document est vide",
  "system.auto.mg6h9h.86": "Cette première image vous permet de vous orienter pendant que GPT Image finalise le brouillon durable.",
  "system.auto.88p135.70": "Cette première version sera automatiquement remplacée par le brouillon finalisé.",
  "system.auto.1bu7nfx.20": "Cet élément s’intègre à",
  "system.auto.nsevj6.138": "Ce brouillon rapide suit le rythme de vos idées. Le générer en qualité maximale enregistre une promotion délibérée et préserve la continuité visuelle.",
  "system.auto.1q1yuj4.52": "Ce jeu de données ne contient aucun justificatif multimédia durable du fournisseur.",
