  "system.auto.1pnroff.101": "Il s’agit d’une image de qualité maximale. Prévisualisez rapidement une autre direction ou poursuivez la conversation pour ajuster le plan.",
  "system.auto.zzqk8z.18": "Il s’agit d’un élément négatif",
  "system.auto.7szj4a.38": "Il s’agit d’une nouvelle direction pour votre travail.",
