  "system.auto.6gtqnq.140": "Voici la requête privée exacte envoyée au flux de génération. Elle peut aider à repérer une formulation involontaire ou une combinaison d’instructions inattendue.",
  "system.auto.1lu3vfg.49": "Voici le texte exact évalué lors de cette simulation.",
