  "system.auto.14nj067.92": "Cette exécution n’a pas enregistré de jeu d’événements complet ; aucune relecture de l’application n’est donc disponible.",
  "system.auto.h3hxv2.105": "Ce contexte créatif enregistré peut être consulté, mais votre rôle actuel dans le projet ne vous permet pas de le modifier.",
