  "system.auto.wj1pfk.42": "Reliez les réactions aux décisions créatives",
  "system.auto.nz1m0q.170": "Repérez les moments où le travail créatif ralentit, échoue, coûte trop cher ou n’aboutit pas, puis vérifiez où Forma aide les créateurs à avancer plus vite et à conserver des décisions plus solides.",
  "system.auto.58ih2n.26": "Historique créatif traçable",
  "system.auto.10w1979.180": "Suit le moment où un même contexte créatif durable devient un texte, une scène scénarisée, une présentation, un storyboard ou une vidéo, sans confondre ces résultats avec la génération d’images fixes.",
