  "system.auto.x5a7xf.37": "% utilisés. La génération réserve jusqu’à",
  "system.auto.7yef3w.181": "Une campagne complète et équilibrée : contexte Library réutilisable, synthèse exploratoire dans Canvas, affinage des documents, tous les formats de sortie, discernement, mémoire, reprise et rétablissement opérationnel.",
  "system.auto.16ycr9a.28": "Une séance de travail réaliste",
  "system.auto.31zt4l.59": "Un traitement sombre et cinématographique pour les créations visuelles et atmosphériques.",
  "system.auto.1faalba.74": "Une décision claire donne une orientation pertinente à tous les résultats à venir.",
  "system.auto.1h5iank.91": "Un récit complet façonné par l’intention du document, ses personnages, son cadre et ses contraintes.",
  "system.auto.16cdrmr.32": "Une séance complète sur le tableau du projet",
  "system.auto.t40q9o.73": "Une étape de composition d’image est explicitement prévue ; aucune étude préliminaire n’a été demandée.",
  "system.auto.1okh7m.75": "Une suite de présentation concise, accompagnée de notes d’orateur et d’une direction visuelle.",
  "system.auto.187px31.60": "Un système sobre et structuré pour la recherche, les preuves et les plans.",
  "system.auto.rz6myk.90": "Une décision relative aux coûts ou aux autorisations doit être examinée avant toute nouvelle intervention d’un fournisseur.",
  "system.auto.6l305a.243": "Un créateur ouvre, parcourt, sélectionne, organise, crée, collabore, demande de l’aide, prépare un document, lance un rendu, examine et récupère son travail ; chaque interaction significative reste mesurable sans conserver les déplacements du curseur ni les saisies brutes.",
  "system.auto.1frok8u.214": "Un créateur commence avec un objectif incertain, rédige un contexte figé et utilise des images, récits, scènes, présentations, storyboards et vidéos conçus pour ses besoins, avec une provenance commune et des justificatifs d’exportation explicites.",
  "system.auto.71pbkw.53": "Une palette réfléchie de couleurs et de relations tonales",
  "system.auto.wfjhxd.43": "Un écueil ou motif à éviter dans le travail",
  "system.auto.1l28vr8.23": "Un terrain après le départ de la foule",
  "system.auto.1mozq04.23": "Un terrain après le départ de la foule",
  "system.auto.fsgk08.105": "Un travail finalisé peut devenir un flux de création hypothétique, réversible et respectueux des droits.",
  "system.auto.1kyjq4d.193": "Un événement local ou une écriture en base de données a échoué pendant que Forma enregistrait cette génération. Aucune panne de fournisseur n’a été signalée. Contactez l’assistance ou consultez les diagnostics de persistance et de stockage des événements du serveur.",
  "system.auto.gz83kn.80": "Un brouillon de faible qualité comporte une intention approuvée par son créateur et une chaîne de résultats en qualité intégrale.",
  "system.auto.bucbhq.75": "Une sélection nommée est compilée en précisant explicitement que sa disposition spatiale n’a pas de portée sémantique.",
  "system.auto.1rd2hm.45": "Une session plus récente de l’espace de travail est déjà en cours de chargement.",
  "system.auto.12lz8mb.75": "Une interprétation animée lisible, rendue par le fournisseur vidéo configuré.",
  "system.auto.huju6j.35": "Un document Canvas préparé précède",
  "system.auto.32whni.92": "Une demande précédente a été bloquée avant toute opération payante ; résolvez le problème du fournisseur avant de réessayer.",
  "system.auto.s6y8bg.72": "Une scène de cinéma ou de télévision exploitable en production, avec actions et dialogues.",
  "system.auto.az96pk.41": "Un projet et un document évoluent à travers l’ensemble des",
  "system.auto.1g314sy.75": "Une exploration prometteuse peut aboutir à un résultat final sans repartir de zéro.",
  "system.auto.1jj1luu.145": "Un brief de reprise, une exécution encadrée de Scout, le jugement humain et un contexte accepté assurent la continuité entre les sessions sans que des agents modifient discrètement le document.",
  "system.auto.hhoo0j.160": "Une référence devient un contexte modifiable, un brouillon est délibérément promu en qualité intégrale et le résultat produit conserve les justificatifs de critique, de bibliothèque et d’exportation.",
  "system.auto.zbg2zm.93": "Une demande portant précisément sur ce résultat est toujours en cours ; aucun autre document ou résultat ne peut la satisfaire.",
  "system.auto.bxjmvu.38": "Une finition éditoriale sobre et réutilisable",
  "system.auto.uhqvi2.209": "Une simulation enregistrée à partir de données réelles reçoit un créateur fictif isolé ; l’administrateur connecté accède à ce compte, confirme une modification protégée, puis revient sans qu’aucun travail synthétique n’entre dans son compte habituel.",
  "system.auto.wcax7k.79": "L’image générée sélectionnée n’est pas disponible ; votre document n’a donc pas été modifié.",
  "system.auto.hcnrqd.70": "Le résultat sélectionné n’est pas disponible ; votre document n’a donc pas été modifié.",
  "system.auto.cwdwfz.59": "Une interruption de session aboutit à une reprise utile, acceptée par une personne.",
  "system.auto.vtxnep.66": "Une prévisualisation plan par plan, rendue sous forme d’images préliminaires reliées.",
  "system.auto.1lzrt0y.91": "Un espace de travail visuel dédié aux documents, décisions, références et résultats créatifs du projet.",
  "system.auto.1wra0hp.97": "Un objet de génération stable et lisible par machine, comprenant des références, des zones de mise en page et des paramètres de prompt.",
  "system.auto.mryzaz.85": "Une hiérarchie de nœuds stable qui préserve les mêmes décisions et relations du document.",
  "system.auto.1dds7wl.209": "Une présentation finale soumise devient une séquence explicitement hypothétique et respectueuse des droits, réunissant contexte déduit, pistes créatives alternatives, décisions acceptées, révision, exportation et nouvelle itération réutilisant le résultat comme entrée.",
  "system.auto.18mq7hd.179": "Une personne explore une idée incertaine à voix haute, met l’aperçu Live en pause, modifie directement deux éléments locaux, compare plusieurs prompts, valide un résultat, quitte la session puis reprend grâce à un brief utile.",
  "system.auto.1vuksmo.81": "Une image enregistrée et validée, sa source, ses droits et l’empreinte de son contenu précèdent l’importation dans la simulation.",
  "system.auto.1kfzq9b.37": "Une référence vidéo n’a pas pu être préparée.",
  "system.auto.1tcsxp2.46": "Un brouillon de travail a justifié une génération en qualité intégrale.",
  "system.auto.b60jtz.41": "Un brouillon de travail a été délibérément porté à l’étape suivante.",
