  "system.auto.11r5fde.213": "La plupart des échecs définitifs sont liés à la sécurité ou à la modération. Avant une nouvelle tentative, affichez le prompt envoyé et les blocs concernés, identifiez la formulation ou la référence probable, puis laissez le créateur modifier uniquement le contexte concerné.",
