  "system.auto.c0m3v4.138": "La production structurée peut conserver des présentations rédigées plus longues, dans la limite de {MAX_MANAGED_PRESENTATION_SLIDES} diapositives pour l’exportation modifiable.",
  "system.auto.1tmoygj.9": "résumés",
  "system.auto.12dfgxb.17": "Équipe activée · {ratio}",
  "system.auto.x2ggib.135": "Le plan de {predictedSlideCount} diapositives développe la trame rédigée de {authoredSlideCount} diapositives ; les diapositives ajoutées doivent rester fondées sur les sources.",
  "system.auto.6sp85k.197": "Les éléments probants {value} sont conservés comme non conformes. La dernière recherche a révélé des écarts sémantiques et des défaillances de sécurité et de fiabilité du fournisseur ; examinez les preuves de la campagne avant de préparer une nouvelle version.",
  "system.auto.rvl0fp.100": "Le storyboard et ses {value} images associées disparaissent ensemble. Une seule annulation permet de restaurer l’ensemble.",
  "system.auto.1fadxmi.116": "Il s’agit d’une contrainte d’exclusion de type {value}. Elle indique ce qui ne doit pas apparaître dans l’aperçu et ne devient jamais un élément à mettre en avant.",
