  "system.auto.j2edve.24": "Voir les {count} résultats",
  "system.auto.1y1zip6.41": "événement visible {formatted} sur {formatted2}",
  "system.auto.13mls3f.30": "Que faut-il exclure concernant {value} ?",
  "system.auto.v8uuz3.118": "Vous avez demandé {itemCount} diapositives, mais le flux de travail structuré conservera l’ensemble des {predictedSlideCount} diapositives créées.",
  "system.auto.lnr6ue.135": "requêtes payantes au total, y compris les corrections de validation et de continuité limitées. Réservation initiale et plafond de dépenses imposé par l’application :",
  "system.auto.1r6h7b9.142": "Forma vérifie le plafond de dépenses restant dans l’application avant chaque requête ou correction du fournisseur. Ce plafond n’est pas imposé par le fournisseur.",
  "system.auto.1ssottd.159": "Déplacer le contenu des événements créés antérieurement vers un stockage effaçable propre à chaque propriétaire ? Les identifiants des événements, les révisions, les autorisations des projets et les résultats terminés seront conservés.",
  "system.auto.j2gqvj.209": "Effacer définitivement le contexte créé et les données de traitement privées temporaires de vos projets personnels ? Les résultats terminés, les fichiers importés, les travaux partagés au sein de l’organisation, les sauvegardes et les données sur d’autres appareils ne seront pas supprimés.",
  "system.auto.1anbigg.71": "Lever cette obligation de conservation légale ? Les éléments de preuve expirés admissibles pourront alors être supprimés.",
  "system.auto.x2egvp.73": "Créer un instantané chiffré de tous les projets que vous êtes autorisé à consulter ?",
  "system.auto.22u9cb.79": "Renouveler la clé de récupération de cette organisation ? Les instantanés existants pourront toujours être déchiffrés.",
  "system.auto.1om1shf.56": "Révoquer immédiatement ce jeton de provisionnement de l’organisation ?",
  "system.auto.1ps0xzg.106": "Transférer la propriété administrative à cet administrateur admissible ? Votre session de projet actuelle sera fermée.",
  "system.auto.1qb2itm.159": "Migrer de manière confidentielle uniquement les événements créés antérieurement au sein de cette organisation avant leur suppression irréversible ? Les autres organisations et les projets personnels resteront inchangés.",
  "system.auto.1lug8ho.166": "Effacer définitivement les projets concernés de l’organisation, leurs sources, les ensembles de contexte, les révisions des résultats, les appartenances et les instantanés de récupération ? Toute obligation de conservation légale active empêchera la suppression.",
  "system.auto.wlcjeh.61": "Cette génération dépasse le budget mensuel restant ({scope}).",
  "system.auto.1skaw5b.124": "Le budget ({scope}) sera utilisé à {percent} %. La génération réserve jusqu’à {reserved} ; il restera {remaining} avant son démarrage.",
  "system.auto.19vmxu0.13": "Section de scène",
