  "system.auto.1rwlbph.212": "Un projet et un document évoluent à travers les 21 types de contexte, un ensemble de contextes réutilisable avec des relations typées entre les références, des modifications réversibles, des résultats d’extraction, des actions sur les objets, des collections partagées et des annotations.",
