  "system.auto.1bymxor.217": "Un projet et un document évoluent à travers les {count} types de contexte, un ensemble de contextes réutilisable avec des relations de référence typées, des modifications réversibles, des résultats d’extraction, des actions sur les objets, des collections partagées et des annotations.",
