  "system.auto.wajp3n.20": "Décisions fondamentales",
  "system.auto.1nw17ge.86": "Proposer → périmètre des différences → accepter/refuser, séquence attendue et texte de commande externalisé.",
  "system.auto.1v1c1m5.150": "Les tableaux de projet, les écritures optimistes ordonnées, le travail spatial virtualisé, le contexte réutilisable et une gouvernance transparente des mises en production partagent une source durable unique.",
  "system.auto.tuivvm.87": "Pages visibles uniquement ; aucune capture des déplacements du pointeur, des frappes, du texte, du microphone ou des données ambiantes de l’appareil.",
  "system.auto.19e5olr.122": "L’approbation d’un fournisseur d’images repose sur des attestations vérifiées de capacités, d’évaluation et de gouvernance, et non sur sa seule configuration.",
  "system.auto.p4eek.66": "Gouvernance, opérations sur les événements, attribution des rôles et toutes les actions de création",
