  "system.auto.f0qlug.108": "Politique pilote v2026-08-10 adoptée : les règles relatives à l’identité, à la confidentialité, aux budgets, aux droits, aux fournisseurs et au partage sont applicables.",
  "system.auto.xckfwq.16": "Sessions et brief",
  "system.auto.h5bu72.136": "Un seul document permet de produire des images, des récits, des scènes, des présentations, des storyboards et des vidéos fondées sur des références, grâce à des tâches persistantes et consultables.",
  "system.auto.16lskvh.39": "$100 par utilisateur · $1,000 par organisation / mois",
  "system.auto.tp7i7l.51": "L’état créatif persistant est reconstitué par réduction des événements.",
  "system.auto.17zll34.62": "Seuls les événements producteurs autorisés transitent par des adaptateurs contrôlés par le serveur",
  "system.auto.bhcaqf.10": "Échanges de discussion",
  "system.auto.uge586.13": "Changements de mode",
  "system.auto.1n4mlgw.5": "Atténué",
  "system.auto.1vtyou0.46": "Choisir la durée, le cadrage et la politique de référence",
  "system.auto.eswhf0.14": "Journal et documentation",
  "system.auto.1m6lim.164": "Le contrôle a été franchi sous surveillance : les briefs issus des événements, la mémoire des parcours rejetés et les métriques de dosage en temps réel continuent de recueillir des preuves pendant que les pilotes en aval se poursuivent.",
  "system.auto.10x97op.27": "Analyses et expérimentations",
  "system.auto.1e9pwmt.137": "Les plafonds de 10 millions de jetons par personne et de 100 millions par organisation sont garantis par des réservations en dollars auprès des fournisseurs, protégées contre les conditions de concurrence.",
  "system.auto.45pmq4.7": "Agents de traitement",
  "system.auto.gbm8h4.60": "Lecture des projections et des vues partagées valides ; aucun droit d’ajout",
  "system.auto.ajx5mz.12": "Mode de travail",
  "system.auto.r6a0yu.5": "Modifications",
  "system.auto.waw2hc.37": "Contraste réduit et associations plus discrètes",
  "system.auto.27712b.6": "Studio",
  "system.auto.ww7671.92": "Pipeline d’ajout D1, compensation, poignées, collections, parcours clavier, administration des événements et relecture.",
  "system.auto.7cvcx3.26": "Vecteurs, familles et corpus",
  "system.auto.gsdskj.145": "Operations et Laboratory sont des espaces chargés indépendamment et adaptés aux autorisations, destinés aux preuves, à la relecture, à l’évaluation des fournisseurs et à l’amélioration du produit.",
  "system.auto.1o17gtf.19": "Juridique et droits relatifs aux données",
  "system.auto.19023pc.54": "Ajoutez les faits ; ne réécrivez jamais sans avertissement le contexte créé par l’utilisateur.",
