  "system.auto.1enz6jw.8": "Sessions",
  "system.auto.iv5ofq.29": "Rendu et adaptateurs de fournisseurs",
  "system.auto.1qu7hnh.159": "Un index pilote versionné et reconstructible regroupe désormais par familles les affirmations pouvant être corrigées et retrouve les précédents cités ; le passage à l’échelle avec pgvector/HNSW reste prévu lors de la migration en production.",
  "system.auto.wtxg6f.28": "Fondements de la conception inclusive",
  "system.auto.1kive7p.46": "Données saisies sous le contrôle de l’utilisateur ; contenu privé conservé 30 jours",
