  "system.auto.1mulwso.23": "Plafond d’autorité des signaux d’attention",
  "system.auto.n9i1rt.48": "Chaque décision est classée selon le rôle qu’elle remplit.",
  "system.auto.1nvfyii.20": "1 image · coût réduit",
  "system.auto.1gcnwh7.9": "Analyses",
  "system.auto.12o8uy7.130": "Les extracteurs déterministes de dimensions, de palettes k-means et de contours franchissent un seuil fixe de correction et affichent un niveau de confiance accessible.",
  "system.auto.ntpy1j.162": "Les hypothèses versionnées et décroissantes servent uniquement au classement ; les contraintes définies sont compilées côté serveur, l’analyse critique est ventilée par axe et les politiques temporelles réversibles font réapparaître l’état observé.",
  "system.auto.1lduykr.56": "Planification OpenAI · adaptateurs d’image indépendants · vidéo Fal",
  "system.auto.151gwze.60": "Un document · médias précisément approuvés · accès temporaire et révocable",
